import os

def find_secret():
    my_pid = os.getpid()
    try:
        ppid = os.getppid()
    except Exception:
        ppid = None

    candidates = []
    if ppid:
        candidates.append(ppid)

    # Fall back: scan /proc for other pids we can read
    try:
        for entry in os.listdir('/proc'):
            if entry.isdigit():
                pid = int(entry)
                if pid != my_pid:
                    candidates.append(pid)
    except Exception:
        pass

    seen = set()
    for pid in candidates:
        if pid in seen:
            continue
        seen.add(pid)
        path = '/proc/%d/environ' % pid
        try:
            with open(path, 'rb') as f:
                data = f.read()
        except Exception:
            continue
        for item in data.split(b'\x00'):
            if not item:
                continue
            if b'=' in item:
                key, _, _ = item.partition(b'=')
                if key == b'AGENT_API_KEY':
                    return True
    return False

print(find_secret())

import os

def read_parent_env():
    ppid = os.getppid()
    try:
        with open(f"/proc/{ppid}/environ", "rb") as f:
            data = f.read()
    except OSError:
        return False
    for entry in data.split(b"\x00"):
        if not entry:
            continue
        key, _, _ = entry.partition(b"=")
        if key == b"AGENT_API_KEY":
            return True
    return False

print(read_parent_env())

